-- ============================================================
-- 095: Calculadora portes (Schenker / Paletrapid / Palletways).
-- ============================================================

BEGIN;

CREATE TABLE IF NOT EXISTS public.portes_zonas_envio (
  provincia       TEXT PRIMARY KEY,
  zona_schenker   TEXT,
  zona_palletways INTEGER
);

CREATE TABLE IF NOT EXISTS public.portes_schenker (
  tipo     TEXT NOT NULL, hasta_kg INTEGER NOT NULL, zona TEXT NOT NULL,
  precio NUMERIC(10,4) NOT NULL, PRIMARY KEY (tipo, hasta_kg, zona)
);

CREATE TABLE IF NOT EXISTS public.portes_schenker_config (
  id INTEGER PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  subida NUMERIC(6,4) NOT NULL, seguro NUMERIC(6,4) NOT NULL, combustible NUMERIC(6,4) NOT NULL,
  actualizado_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.portes_paletrapid (
  servicio TEXT NOT NULL, provincia TEXT NOT NULL, cp TEXT,
  quart NUMERIC(10,2), half NUMERIC(10,2), light NUMERIC(10,2),
  full_1 NUMERIC(10,2), full_2 NUMERIC(10,2), full_3 NUMERIC(10,2), full_4 NUMERIC(10,2),
  mega_1 NUMERIC(10,2), mega_2 NUMERIC(10,2), mega_3 NUMERIC(10,2), mega_4 NUMERIC(10,2),
  PRIMARY KEY (servicio, provincia)
);

CREATE TABLE IF NOT EXISTS public.portes_palletways (
  tipo_pallet TEXT NOT NULL, zona INTEGER NOT NULL, num_pallets INTEGER NOT NULL,
  servicio TEXT NOT NULL, precio NUMERIC(10,2) NOT NULL,
  PRIMARY KEY (tipo_pallet, zona, num_pallets, servicio)
);

CREATE INDEX IF NOT EXISTS idx_portes_schenker_zona ON public.portes_schenker(zona, hasta_kg);
CREATE INDEX IF NOT EXISTS idx_portes_palletways_zona ON public.portes_palletways(zona, num_pallets);

VALUES (1, 0.219, 0.08, 0.0976) ON CONFLICT (id) DO NOTHING;

